pub fn apply(&mut self, delta: Delta) -> Result<(), SyncError> {
    if delta.seq <= self.seq {
        return Ok(()); // already applied
    }
    self.rows.insert(delta.id, delta.row);
    self.seq = delta.seq;
    Ok(())
}

